import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { type RosterRecord, rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'delivery-store',
  description:
    "Read and update client delivery: projects.json and milestones.json (rosters). action:'status' for what is waiting on clients, late and due soon; 'report' for a project's weekly status; 'add_project' and 'add_milestone' to save one (an existing title is updated, never duplicated; shiftDays moves dates by a number of days); 'set_status' to move a milestone between planned, in-progress, waiting (sent to the client for approval) and approved; 'list' for every project and milestone.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'report', 'add_project', 'add_milestone', 'set_status', or 'list'.",
      required: true,
    },
    id: {
      type: 'string',
      description: "A milestone id like 'ms-4' (for add_project, a project id like 'pr-2').",
    },
    title: {
      type: 'string',
      description: "The milestone's (or for add_project, the project's) title. Also finds it when no id is given.",
    },
    project: { type: 'string', description: "The project's id or name, e.g. 'pr-1' or 'Juniper website'." },
    client: { type: 'string', description: 'The client, e.g. Juniper Press.' },
    contact: { type: 'string', description: 'Who approves on the client side.' },
    lead: { type: 'string', description: "Who leads the project on the studio's side." },
    owner: { type: 'string', description: 'Who owns the milestone.' },
    dueAt: { type: 'string', description: 'The due date, YYYY-MM-DD.' },
    shiftDays: {
      type: 'number',
      description:
        "Move the due date by this many days (negative pulls it in). On a project, moves the project's date and every milestone not yet approved.",
    },
    status: { type: 'string', description: 'A project: proposed, active, on-hold, or done. A milestone: planned, in-progress, waiting, or approved.' },
    note: { type: 'string', description: 'What happened, with the client’s feedback in their words.' },
    withinDays: { type: 'number', description: 'How many days ahead counts as due soon (default 14).' },
  },
  outputs: {
    active: { type: 'number', description: 'Active projects.' },
    waiting: { type: 'number', description: 'Milestones waiting on a client.' },
    late: { type: 'number', description: 'Milestones past due and not with the client.' },
    dueSoon: { type: 'number', description: 'Open milestones due within the window.' },
    summary: { type: 'string', description: 'What changed first, then the delivery picture (or the report or listing).' },
  },
  requires: ['workspace.read', 'workspace.write'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── delivery-rules-start ──
// Pure derivations: local calendar days, date shifts, milestone and project
// health, and the lines the crew reads. Kept self-contained between these
// sentinels so tests (and the page's demo) execute the shipped bytes.
var DAY_MS = 86400000;
var PROJECT_STAGES = ['proposed', 'active', 'on-hold', 'done'];
var MILESTONE_STAGES = ['planned', 'in-progress', 'waiting', 'approved'];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
function localDay(ms) {
  var d = new Date(ms);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
}
function isDay(text) {
  return /^\d{4}-\d{2}-\d{2}$/.test(String(text || ''));
}
function normalizeDate(text, nowMs) {
  var raw = String(text || '').trim();
  if (isDay(raw)) return raw;
  // Only something that reads as a date: a month name with a day, or numbers like 12/10.
  if (!/\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?\s+\d|\d\s+(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)|\d{1,4}[/.-]\d{1,2}[/.-]\d{1,4}/i.test(raw)) return null;
  if (/\d{4}/.test(raw)) {
    var full = Date.parse(raw);
    return isFinite(full) ? localDay(full) : null;
  }
  // 'December 10' names the next December 10, not one in 2001.
  var now = new Date(nowMs || Date.now());
  var parsed = Date.parse(raw + ' ' + now.getFullYear());
  if (!isFinite(parsed)) return null;
  if (parsed < now.getTime() - 31 * DAY_MS) parsed = Date.parse(raw + ' ' + (now.getFullYear() + 1));
  return localDay(parsed);
}
function daysLeft(day, nowMs) {
  var due = Date.parse(String(day).slice(0, 10) + 'T00:00:00');
  var today = Date.parse(localDay(nowMs) + 'T00:00:00');
  return Math.round((due - today) / DAY_MS);
}
function shiftDay(day, days) {
  var d = new Date(String(day).slice(0, 10) + 'T12:00:00');
  d.setDate(d.getDate() + Math.round(days));
  return localDay(d.getTime());
}
function when(days) {
  if (days < 0) return -days + (days === -1 ? ' day late' : ' days late');
  if (days === 0) return 'due today';
  return 'due in ' + days + (days === 1 ? ' day' : ' days');
}
function key(text) {
  return String(text || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9&]+/g, ' ')
    .trim();
}
// 'exact', 'partial' (the title starts with the words given, contains them whole, or holds every word given), or ''.
function titleMatch(title, wanted) {
  var have = key(title);
  var want = key(wanted);
  if (!have || !want) return '';
  if (have === want) return 'exact';
  if ((' ' + have).indexOf(' ' + want) >= 0 || (' ' + want + ' ').indexOf(' ' + have + ' ') >= 0) return 'partial';
  var words = want.split(' ').filter(function (w) {
    return w.length > 2 && ['the', 'and', 'for'].indexOf(w) < 0;
  });
  return words.length && words.every(function (w) { return (' ' + have).indexOf(' ' + w) >= 0; }) ? 'partial' : '';
}
function waitedDays(m, nowMs) {
  return m.fields && isDay(m.fields.sentAt) ? Math.max(0, -daysLeft(m.fields.sentAt, nowMs)) : 0;
}
function isLate(m, nowMs) {
  return m.status !== 'approved' && m.status !== 'waiting' && isDay(m.fields && m.fields.dueAt) && daysLeft(m.fields.dueAt, nowMs) < 0;
}
function milestonesOf(projectId, milestones) {
  return milestones
    .filter(function (m) { return m.fields && m.fields.projectId === projectId; })
    .sort(function (a, b) { return String(a.fields.dueAt || '9999').localeCompare(String(b.fields.dueAt || '9999')); });
}
function health(project, milestones, nowMs) {
  if (project.status === 'done') return 'done';
  var mine = milestonesOf(project.id, milestones);
  if (mine.some(function (m) { return isLate(m, nowMs); })) return 'late';
  if (
    mine.some(function (m) {
      return m.status === 'waiting' && (waitedDays(m, nowMs) >= 5 || (isDay(m.fields.dueAt) && daysLeft(m.fields.dueAt, nowMs) < 0));
    })
  ) return 'at risk';
  return 'on track';
}
function milestoneLine(m, project, nowMs) {
  var f = m.fields || {};
  var head = f.title + ' (' + m.id + ', ' + (project ? project.fields.title : 'no project') + ')';
  if (m.status === 'approved') return head + ' approved' + (f.approvedAt ? ' ' + f.approvedAt : '');
  if (m.status === 'waiting') {
    var waited = waitedDays(m, nowMs);
    return (
      head + ' with ' + (f.approver || (project && project.fields.contact) || 'the client') + ' for approval ' +
      (waited === 0 ? 'since today' : 'for ' + waited + (waited === 1 ? ' day' : ' days')) +
      ', round ' + (f.rounds || 1) + (isDay(f.dueAt) ? ', ' + when(daysLeft(f.dueAt, nowMs)) : '')
    );
  }
  return head + ' ' + m.status + (isDay(f.dueAt) ? ', ' + when(daysLeft(f.dueAt, nowMs)) + ' (' + f.dueAt + ')' : ', no date') + (f.owner ? ', owner ' + f.owner : '');
}
function deliveryPicture(projects, milestones, nowMs, withinDays) {
  var byId = {};
  projects.forEach(function (p) { byId[p.id] = p; });
  var active = projects.filter(function (p) { return p.status === 'active'; });
  var live = milestones.filter(function (m) {
    var p = byId[m.fields && m.fields.projectId];
    return p && p.status === 'active' && m.status !== 'approved';
  });
  var waiting = live
    .filter(function (m) { return m.status === 'waiting'; })
    .sort(function (a, b) { return waitedDays(b, nowMs) - waitedDays(a, nowMs); });
  var late = live.filter(function (m) { return isLate(m, nowMs); });
  // One list, late first: asked what's due, a model read a separate late list as out of scope.
  var due = live
    .filter(function (m) { return isDay(m.fields.dueAt) && daysLeft(m.fields.dueAt, nowMs) <= withinDays; })
    .sort(function (a, b) { return String(a.fields.dueAt).localeCompare(String(b.fields.dueAt)); });
  var line = function (m) { return milestoneLine(m, byId[m.fields.projectId], nowMs); };
  var parts = [
    active.length + (active.length === 1 ? ' active project' : ' active projects') + ', ' + waiting.length + ' waiting on clients, ' + late.length + ' late on our side.',
  ];
  parts.push(waiting.length ? 'Waiting on clients, longest first: ' + waiting.map(line).join(' | ') + '.' : 'Nothing is waiting on a client.');
  parts.push(
    due.length
      ? 'Due within ' + withinDays + ' days, late first: ' + due.map(line).join(' | ') + '.'
      : 'Nothing due in the next ' + withinDays + ' days.',
  );
  parts.push(
    active.length
      ? 'Projects: ' + active.map(function (p) {
          var next = milestonesOf(p.id, milestones).filter(function (m) { return m.status !== 'approved'; })[0];
          return p.fields.title + ' (' + p.id + ', ' + (p.fields.client || 'no client') + (p.fields.lead ? ', lead ' + p.fields.lead : '') + (isDay(p.fields.dueAt) ? ', due ' + p.fields.dueAt : '') + ') ' + health(p, milestones, nowMs) + (next ? '; next: ' + next.fields.title + ' (' + next.status + ')' : '; every milestone approved');
        }).join(' | ') + '.'
      : 'No active projects.',
  );
  var other = projects.filter(function (p) { return p.status !== 'active'; });
  if (other.length) parts.push('Also: ' + other.map(function (p) { return p.fields.title + ' (' + p.id + ', ' + p.status + ')'; }).join(', ') + '.');
  return { active: active.length, waiting: waiting.length, late: late.length, dueSoon: due.length, summary: parts.join(' ') };
}
function weeklyReport(project, milestones, nowMs) {
  var mine = milestonesOf(project.id, milestones);
  var weekAgo = localDay(nowMs - 7 * DAY_MS);
  var done = mine.filter(function (m) { return m.status === 'approved' && String(m.fields.approvedAt || '') >= weekAgo; });
  var waiting = mine.filter(function (m) { return m.status === 'waiting'; });
  var working = mine.filter(function (m) { return m.status === 'in-progress'; });
  var next = mine.filter(function (m) { return m.status === 'planned'; }).slice(0, 2);
  var client = project.fields.client || 'the client';
  var list = function (items, fn) { return items.length ? items.map(fn).join('; ') : 'nothing'; };
  return (
    project.fields.title + ' (' + project.id + ') for ' + client + ', week of ' + localDay(nowMs) + ', ' + health(project, milestones, nowMs) + '. ' +
    'Approved in the last 7 days: ' + list(done, function (m) { return m.fields.title + ' (' + m.fields.approvedAt + ')'; }) + '. ' +
    'Waiting on ' + client + ': ' + list(waiting, function (m) { return m.fields.title + ', sent ' + (m.fields.sentAt || 'recently') + ', round ' + (m.fields.rounds || 1); }) + '. ' +
    'In progress: ' + list(working, function (m) { return m.fields.title + (isDay(m.fields.dueAt) ? ', ' + when(daysLeft(m.fields.dueAt, nowMs)) + ' (' + m.fields.dueAt + ')' : '') + (m.fields.owner ? ', ' + m.fields.owner : ''); }) + '. ' +
    'Next up: ' + list(next, function (m) { return m.fields.title + (isDay(m.fields.dueAt) ? ', due ' + m.fields.dueAt : ''); }) + '.' +
    (isDay(project.fields.dueAt) ? ' Project due ' + project.fields.dueAt + '.' : '')
  );
}
// ── delivery-rules-end ──

const projects = rosterStore(gezel.fs, 'projects.json', { stages: ['proposed', 'active', 'on-hold', 'done'], idPrefix: 'pr' });
const milestones = rosterStore(gezel.fs, 'milestones.json', {
  stages: ['planned', 'in-progress', 'waiting', 'approved'],
  idPrefix: 'ms',
});

function choose(all: RosterRecord[], wanted: string, what: string, label: (r: RosterRecord) => string): RosterRecord | null {
  const exact = all.filter((r) => titleMatch(r.fields.title, wanted) === 'exact');
  if (exact.length === 1) return exact[0]!;
  const partial = exact.length > 1 ? exact : all.filter((r) => titleMatch(r.fields.title, wanted) === 'partial' || titleMatch(r.fields.client, wanted) === 'exact');
  if (partial.length === 1) return partial[0]!;
  if (partial.length > 1) throw new Error('More than one ' + what + " matches '" + wanted + "': " + partial.map(label).join(', ') + '. Pass id.');
  return null;
}
async function resolveProject(text: string | undefined): Promise<RosterRecord> {
  const all = await projects.list();
  if (!text) throw new Error("Pass 'project' (an id like 'pr-1' or its name). Projects: " + (all.map((p) => p.id + ' ' + String(p.fields.title)).join(', ') || 'none') + '.');
  const byId = all.find((p) => p.id === text.trim());
  if (byId) return byId;
  // 'Juniper' means the client's active project before its proposed or finished ones.
  const label = (p: RosterRecord) => p.id + ' ' + String(p.fields.title);
  const found = choose(all.filter((p) => p.status === 'active'), text, 'project', label) ?? choose(all, text, 'project', label);
  if (found) return found;
  throw new Error("No project matches '" + text + "'. Projects: " + (all.map((p) => p.id + ' ' + String(p.fields.title)).join(', ') || 'none') + '.');
}
async function resolveMilestone(): Promise<RosterRecord> {
  const all = await milestones.list();
  if (input.id) {
    const byId = all.find((m) => m.id === input.id);
    if (byId) return byId;
    throw new Error("No milestone with id '" + input.id + "'.");
  }
  if (!input.title) throw new Error("Pass the milestone's 'id' (e.g. 'ms-4') or 'title'.");
  const scoped = input.project ? milestonesOf((await resolveProject(input.project)).id, all) : all;
  const names: Record<string, string> = {};
  (await projects.list()).forEach((p) => (names[p.id] = String(p.fields.title)));
  const found = choose(scoped, input.title, 'milestone', (m) => m.id + ' ' + String(m.fields.title) + ' (' + names[String(m.fields.projectId)] + ')');
  if (found) return found;
  throw new Error("No milestone matches '" + input.title + "'. Call list_client_projects to see them, or add it with add_milestone.");
}
function checkDate(text: string | undefined, label: string): string | null {
  if (!text) return null;
  const day = normalizeDate(text);
  if (!day) throw new Error(label + " must be a date, e.g. '2026-12-01'.");
  return day;
}
function shift(input: { shiftDays?: number }): number {
  return typeof input.shiftDays === 'number' && isFinite(input.shiftDays) ? Math.round(input.shiftDays) : 0;
}

const today = localDay(Date.now());
const withinDays = typeof input.withinDays === 'number' && input.withinDays > 0 ? Math.round(input.withinDays) : 14;
let note = '';
let reply = '';

if (input.action === 'add_project') {
  if (!input.title && !input.id) throw new Error("add_project needs 'title'.");
  if (input.status && !PROJECT_STAGES.includes(input.status)) throw new Error('A project is proposed, active, on-hold, or done.');
  const all = await projects.list();
  const existing = input.id ? all.find((p) => p.id === input.id) : all.find((p) => titleMatch(p.fields.title, input.title) === 'exact');
  if (input.id && !existing) throw new Error("No project with id '" + input.id + "'.");
  const dueAt = checkDate(input.dueAt, 'dueAt');
  const fields: Record<string, unknown> = {
    ...(input.id && input.title ? { title: input.title.trim() } : {}),
    ...(input.client ? { client: input.client.trim() } : {}),
    ...(input.contact ? { contact: input.contact.trim() } : {}),
    ...(input.lead ? { lead: input.lead.trim() } : {}),
    ...(dueAt ? { dueAt } : {}),
    ...(input.note ? { notes: input.note.trim() } : {}),
  };
  const days = shift(input);
  if (existing) {
    if (days && !dueAt && isDay(existing.fields.dueAt)) fields.dueAt = shiftDay(String(existing.fields.dueAt), days);
    await projects.update(existing.id, { fields });
    if (input.status && input.status !== existing.status) await projects.transition(existing.id, input.status, input.note ? { note: input.note } : {});
    let moved = 0;
    if (days) {
      for (const m of milestonesOf(existing.id, await milestones.list())) {
        if (m.status === 'approved' || !isDay(m.fields.dueAt)) continue;
        await milestones.update(m.id, { fields: { dueAt: shiftDay(String(m.fields.dueAt), days) }, note: 'Moved ' + days + ' days with the project' });
        moved++;
      }
    }
    note =
      'Updated ' + String(fields.title ?? existing.fields.title) + '.' +
      (days ? ' Moved ' + (days > 0 ? 'out' : 'in') + ' by ' + Math.abs(days) + (Math.abs(days) === 1 ? ' day' : ' days') + (isDay(fields.dueAt) ? ', now due ' + String(fields.dueAt) : '') + ', with ' + moved + (moved === 1 ? ' open milestone.' : ' open milestones.') : '');
  } else {
    if (!input.client) {
      const near = all.filter((p) => titleMatch(p.fields.title, input.title) === 'partial');
      throw new Error(
        (near.length ? "No project is titled exactly '" + input.title + "'. Did you mean " + near.map((p) => p.id + ' ' + String(p.fields.title)).join(' or ') + '? Pass its id to change it, or ' : 'A new project needs ') +
          "'client' to add a new one.",
      );
    }
    const record = await projects.add({ status: input.status ?? 'active', fields: { title: String(input.title).trim(), ...fields } });
    note = 'Added ' + record.id + ', ' + String(input.title).trim() + ' for ' + input.client.trim() + '.';
  }
} else if (input.action === 'add_milestone') {
  if (!input.title && !input.id) throw new Error("add_milestone needs 'title'.");
  if (input.status && !MILESTONE_STAGES.includes(input.status)) throw new Error('A milestone is planned, in-progress, waiting, or approved.');
  const all = await milestones.list();
  let existing: RosterRecord | undefined;
  let project: RosterRecord | null = null;
  if (input.id) {
    existing = all.find((m) => m.id === input.id);
    if (!existing) throw new Error("No milestone with id '" + input.id + "'.");
  } else {
    project = input.project ? await resolveProject(input.project) : null;
    const pool = project ? milestonesOf(project.id, all) : all;
    const same = pool.filter((m) => titleMatch(m.fields.title, input.title) === 'exact');
    if (same.length > 1) throw new Error("More than one milestone is titled '" + input.title + "'. Pass project or id.");
    existing = same[0];
  }
  const dueAt = checkDate(input.dueAt, 'dueAt');
  const days = shift(input);
  const fields: Record<string, unknown> = {
    ...(input.id && input.title ? { title: input.title.trim() } : {}),
    ...(dueAt ? { dueAt } : {}),
    ...(input.owner ? { owner: input.owner.trim() } : {}),
    ...(input.note ? { notes: input.note.trim() } : {}),
  };
  if (existing) {
    if (days && !dueAt) {
      if (!isDay(existing.fields.dueAt)) throw new Error(String(existing.fields.title) + " has no due date to move; pass 'dueAt'.");
      fields.dueAt = shiftDay(String(existing.fields.dueAt), days);
    }
    await milestones.update(existing.id, { fields, ...(days ? { note: 'Moved ' + days + ' days' } : {}) });
    if (input.status && input.status !== existing.status) await milestones.transition(existing.id, input.status, input.note ? { note: input.note } : {});
    note =
      'Updated ' + String(fields.title ?? existing.fields.title) + (isDay(fields.dueAt) ? ', now due ' + String(fields.dueAt) : '') +
      (days ? ' (' + (days > 0 ? 'moved out ' : 'pulled in ') + Math.abs(days) + (Math.abs(days) === 1 ? ' day' : ' days') + ')' : '') + '.';
  } else {
    if (!project) throw new Error("A new milestone needs 'project' (its id or name).");
    if (!dueAt) throw new Error("A new milestone needs 'dueAt' (YYYY-MM-DD).");
    const record = await milestones.add({
      status: input.status ?? 'planned',
      fields: { projectId: project.id, title: String(input.title).trim(), rounds: 0, ...fields },
    });
    note = 'Added ' + record.id + ', ' + String(input.title).trim() + ' on ' + String(project.fields.title) + ', due ' + dueAt + '.';
  }
} else if (input.action === 'set_status') {
  if (!input.status || !MILESTONE_STAGES.includes(input.status)) throw new Error("set_status needs status 'planned', 'in-progress', 'waiting', or 'approved'.");
  const m = await resolveMilestone();
  const project = (await projects.get(String(m.fields.projectId))) ?? null;
  const fields: Record<string, unknown> = {};
  if (input.status === 'waiting' && m.status !== 'waiting') {
    fields.sentAt = today;
    fields.rounds = (Number(m.fields.rounds) || 0) + 1;
    fields.approver = input.contact ? input.contact.trim() : String(project?.fields.contact ?? m.fields.approver ?? '') || undefined;
  }
  if (input.status === 'approved' && m.status !== 'approved') fields.approvedAt = today;
  if (m.status === 'waiting' && input.status === 'in-progress' && input.note) fields.feedback = input.note.trim();
  if (Object.keys(fields).length) await milestones.update(m.id, { fields });
  if (input.status !== m.status) await milestones.transition(m.id, input.status, input.note ? { note: input.note } : {});
  const title = String(m.fields.title);
  const on = project ? ' (' + String(project.fields.title) + ')' : '';
  note =
    m.status === input.status
      ? title + on + ' was already ' + input.status + '.'
      : input.status === 'approved'
        ? title + on + ' is approved.'
        : input.status === 'waiting'
          ? title + on + ' went to ' + String(fields.approver || 'the client') + ' for approval, round ' + String(fields.rounds) + '.'
          : m.status === 'waiting' && input.status === 'in-progress'
            ? title + on + ' came back with changes and is in progress again' + (input.note ? ': ' + input.note.trim() : '') + '.'
            : title + on + ' is now ' + input.status + '.';
} else if (input.action === 'report') {
  const all = await projects.list();
  const ms = await milestones.list();
  const chosen = input.project ? [await resolveProject(input.project)] : all.filter((p) => p.status === 'active');
  reply = chosen.map((p) => weeklyReport(p, ms, Date.now())).join('\n\n') || 'No active projects to report on.';
} else if (input.action === 'list') {
  const ms = await milestones.list();
  reply =
    (await projects.list())
      .map(
        (p) =>
          '[' + p.status + '] ' + String(p.fields.title) + ' (' + p.id + ', ' + String(p.fields.client ?? 'no client') + (p.fields.lead ? ', lead ' + String(p.fields.lead) : '') + (isDay(p.fields.dueAt) ? ', due ' + String(p.fields.dueAt) : '') + '): ' +
          (milestonesOf(p.id, ms).map((m) => milestoneLine(m, p, Date.now())).join(' | ') || 'no milestones yet'),
      )
      .join('\n') || 'No projects yet.';
} else if (input.action !== 'status') {
  throw new Error("Unknown action '" + input.action + "'. Use status, report, add_project, add_milestone, set_status, or list.");
}

const view = deliveryPicture(await projects.list(), await milestones.list(), Date.now(), withinDays);
gezel.output({
  active: view.active,
  waiting: view.waiting,
  late: view.late,
  dueSoon: view.dueSoon,
  summary: reply || (note ? note + ' ' : '') + view.summary,
});

